import sys
from collections import Counter

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    count = Counter(a)
    unique_sorted = sorted(count.keys())

    inc = []
    dec = []

    for num in unique_sorted:
        if count[num] > 2:
            print("NO")
            return
        elif count[num] == 2:
            if not inc or inc[-1] < num:
                inc.append(num)
            else:
                if not dec or dec[-1] > num:
                    dec.append(num)
                else:
                    print("NO")
                    return
        else:
            if not inc or inc[-1] < num:
                inc.extend([num] * count[num])
            else:
                dec.extend([num] * count[num])

    if inc and dec and inc[-1] >= dec[0]:
        print("NO")
        return

    print("YES")
    print(len(inc))
    print(*inc)
    print(len(dec))
    print(*dec)

if __name__ == "__main__":
    main()
